svg.script:
//
(function() {
  function init() {
    const svg = document.getElementById("exv-root");
    if (!svg || svg.hasAttribute("data-init-done")) return;
    svg.setAttribute("data-init-done", "true");

    const btnInit = svg.getElementById("exv-btn-init");
    const btnAdv = svg.getElementById("exv-btn-adv");
    const hotspots = svg.querySelectorAll(".exv-hotspot-trigger");
    const closeBtn = svg.getElementById("exv-hotspot-close");

    if (btnInit) {
      btnInit.addEventListener("click", () => {
        svg.classList.remove("exv-is-advanced");
        svg.classList.remove("exv-show-hotspot");
      });
    }

    if (btnAdv) {
      btnAdv.addEventListener("click", () => {
        svg.classList.add("exv-is-advanced");
      });
    }

    hotspots.forEach(hotspot => {
      hotspot.addEventListener("click", (e) => {
        e.stopPropagation();
        svg.classList.add("exv-is-advanced");
        svg.classList.add("exv-show-hotspot");
      });
    });

    if (closeBtn) {
      closeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        svg.classList.remove("exv-show-hotspot");
      });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
//
